import{_ as e,o as a,c as d,a5 as n}from"./chunks/framework.a5no_H3L.js";const p=JSON.parse('{"title":"Spring 常用注解速查","description":"适用 Spring Framework 6.x / Spring Boot 3.x。范围限定在核心容器、Spring Web MVC 与 Spring Boot 启动相关注解；Spring Security、Spring Data、测试注解不在本页，见各自专题。","frontmatter":{"type":"reference","level":"intermediate"},"headers":[],"relativePath":"spring/reference/annotations.md","filePath":"spring/reference/annotations.md"}'),l={name:"spring/reference/annotations.md"};function r(i,t,o,c,s,f){return a(),d("div",null,[...t[0]||(t[0]=[n('<h1 id="spring-常用注解速查" tabindex="-1" data-src-line="2" data-src-file="spring/reference/annotations.md">Spring 常用注解速查 <a class="header-anchor" href="#spring-常用注解速查" aria-label="Permalink to &quot;Spring 常用注解速查&quot;">​</a></h1><blockquote data-src-line="4" data-src-file="spring/reference/annotations.md"><p data-src-line="4" data-src-file="spring/reference/annotations.md">适用 Spring Framework 6.x / Spring Boot 3.x。范围限定在核心容器、Spring Web MVC 与 Spring Boot 启动相关注解；Spring Security、Spring Data、测试注解不在本页，见各自专题。</p></blockquote><p data-src-line="6" data-src-file="spring/reference/annotations.md">本页只回答两件事：这个注解做什么，使用它有什么限制或默认行为。用法示例和取舍放在对应专题页面。</p><h2 id="启动与配置" tabindex="-1" data-src-line="8" data-src-file="spring/reference/annotations.md">启动与配置 <a class="header-anchor" href="#启动与配置" aria-label="Permalink to &quot;启动与配置&quot;">​</a></h2><table tabindex="0"><thead data-src-line="10" data-src-file="spring/reference/annotations.md"><tr data-src-line="10" data-src-file="spring/reference/annotations.md"><th style="text-align:left;">注解</th><th style="text-align:left;">作用</th><th style="text-align:left;">约束与默认值</th></tr></thead><tbody data-src-line="12" data-src-file="spring/reference/annotations.md"><tr data-src-line="12" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@SpringBootApplication</code></td><td style="text-align:left;">组合 <code>@SpringBootConfiguration</code>、<code>@EnableAutoConfiguration</code>、<code>@ComponentScan</code></td><td style="text-align:left;">通常标在主启动类上，测试框架靠它定位配置；<code>exclude</code>、<code>scanBasePackages</code> 通过 <code>@AliasFor</code> 转发给被组合的注解</td></tr><tr data-src-line="13" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@EnableAutoConfiguration</code></td><td style="text-align:left;">打开自动配置</td><td style="text-align:left;">注册 <code>AutoConfigurationImportSelector</code>；<code>spring.boot.enableautoconfiguration=false</code> 可整体关闭，<code>exclude</code>/<code>excludeName</code> 排除单个配置类</td></tr><tr data-src-line="14" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@ComponentScan</code></td><td style="text-align:left;">扫描组件</td><td style="text-align:left;">默认扫描注解所在包及子包；可用 <code>basePackages</code>、<code>excludeFilters</code> 缩小范围</td></tr><tr data-src-line="15" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Configuration</code></td><td style="text-align:left;">声明配置类</td><td style="text-align:left;"><code>proxyBeanMethods</code> 默认 <code>true</code>；设为 <code>false</code> 后 <code>@Bean</code> 方法之间不能互相调用，只能通过方法参数注入</td></tr><tr data-src-line="16" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Import</code></td><td style="text-align:left;">导入其他配置</td><td style="text-align:left;">可导入配置类、普通类（注册为 Bean）、<code>ImportSelector</code> 或 <code>ImportBeanDefinitionRegistrar</code></td></tr></tbody></table><h2 id="bean-定义与注入" tabindex="-1" data-src-line="18" data-src-file="spring/reference/annotations.md">Bean 定义与注入 <a class="header-anchor" href="#bean-定义与注入" aria-label="Permalink to &quot;Bean 定义与注入&quot;">​</a></h2><table tabindex="0"><thead data-src-line="20" data-src-file="spring/reference/annotations.md"><tr data-src-line="20" data-src-file="spring/reference/annotations.md"><th style="text-align:left;">注解</th><th style="text-align:left;">作用</th><th style="text-align:left;">约束与默认值</th></tr></thead><tbody data-src-line="22" data-src-file="spring/reference/annotations.md"><tr data-src-line="22" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Bean</code></td><td style="text-align:left;">声明 Bean</td><td style="text-align:left;">默认以方法名作为 Bean 名；方法返回值类型用于 <code>@ConditionalOnMissingBean</code> 的推断</td></tr><tr data-src-line="23" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Component</code></td><td style="text-align:left;">通用组件</td><td style="text-align:left;"><code>@Service</code>、<code>@Repository</code>、<code>@Controller</code> 都以它为元注解</td></tr><tr data-src-line="24" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Service</code></td><td style="text-align:left;">业务层组件</td><td style="text-align:left;">与 <code>@Component</code> 行为相同，只表达分层语义</td></tr><tr data-src-line="25" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Repository</code></td><td style="text-align:left;">持久层组件</td><td style="text-align:left;">在 <code>@Component</code> 基础上增加持久层异常转换</td></tr><tr data-src-line="26" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Autowired</code></td><td style="text-align:left;">按类型注入</td><td style="text-align:left;">只有一个构造器时可省略；字段注入无法配合 <code>final</code> 字段</td></tr><tr data-src-line="27" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Qualifier</code></td><td style="text-align:left;">按名称收窄候选</td><td style="text-align:left;">与 <code>@Autowired</code> 搭配，也可标在 <code>@Bean</code> 方法参数上</td></tr><tr data-src-line="28" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Primary</code></td><td style="text-align:left;">同类型多候选时优先</td><td style="text-align:left;">与 <code>@Qualifier</code> 同时出现时，<code>@Qualifier</code> 的收窄优先</td></tr><tr data-src-line="29" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Scope</code></td><td style="text-align:left;">指定作用域</td><td style="text-align:left;">默认 <code>singleton</code>；<code>prototype</code> 每次获取都创建新实例</td></tr><tr data-src-line="30" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Lazy</code></td><td style="text-align:left;">延迟初始化</td><td style="text-align:left;">标在注入点上注入的是代理，首次调用才解析目标 Bean</td></tr><tr data-src-line="31" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Value</code></td><td style="text-align:left;">注入单个配置值</td><td style="text-align:left;">支持 <code>${key:default}</code> 与 SpEL；多层结构改用 <code>@ConfigurationProperties</code></td></tr><tr data-src-line="32" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@ConfigurationProperties</code></td><td style="text-align:left;">绑定一组配置</td><td style="text-align:left;">必须注册为 Bean：<code>@EnableConfigurationProperties</code>、<code>@ConfigurationPropertiesScan</code> 或 <code>@Component</code> 三者之一</td></tr><tr data-src-line="33" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Profile</code></td><td style="text-align:left;">按环境生效</td><td style="text-align:left;">未激活任何 profile 时，只有声明为 <code>default</code> 的 <code>@Profile</code> Bean 生效；未标注的 Bean 始终生效</td></tr></tbody></table><h2 id="web-请求处理" tabindex="-1" data-src-line="35" data-src-file="spring/reference/annotations.md">Web 请求处理 <a class="header-anchor" href="#web-请求处理" aria-label="Permalink to &quot;Web 请求处理&quot;">​</a></h2><table tabindex="0"><thead data-src-line="37" data-src-file="spring/reference/annotations.md"><tr data-src-line="37" data-src-file="spring/reference/annotations.md"><th style="text-align:left;">注解</th><th style="text-align:left;">作用</th><th style="text-align:left;">约束与默认值</th></tr></thead><tbody data-src-line="39" data-src-file="spring/reference/annotations.md"><tr data-src-line="39" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Controller</code></td><td style="text-align:left;">MVC 控制器</td><td style="text-align:left;">返回值走视图解析；返回 JSON 用 <code>@RestController</code></td></tr><tr data-src-line="40" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@RestController</code></td><td style="text-align:left;">返回值直接写入响应体</td><td style="text-align:left;">等于 <code>@Controller</code> 加 <code>@ResponseBody</code></td></tr><tr data-src-line="41" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@RequestMapping</code></td><td style="text-align:left;">映射请求路径</td><td style="text-align:left;">可标在类和方法上，两级路径拼接</td></tr><tr data-src-line="42" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@GetMapping</code> / <code>@PostMapping</code></td><td style="text-align:left;">限定 HTTP 方法的映射</td><td style="text-align:left;">等价于 <code>@RequestMapping(method = ...)</code>；同类还有 <code>@PutMapping</code>、<code>@DeleteMapping</code>、<code>@PatchMapping</code></td></tr><tr data-src-line="43" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@PathVariable</code></td><td style="text-align:left;">提取路径变量</td><td style="text-align:left;">参数名依赖 <code>-parameters</code> 编译参数，名字不一致时显式写 <code>value</code></td></tr><tr data-src-line="44" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@RequestParam</code></td><td style="text-align:left;">提取查询参数</td><td style="text-align:left;"><code>required</code> 默认 <code>true</code>，缺失时返回 400；可用 <code>defaultValue</code> 放宽</td></tr><tr data-src-line="45" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@RequestBody</code></td><td style="text-align:left;">绑定请求体</td><td style="text-align:left;">依赖 <code>HttpMessageConverter</code>；<code>Content-Type</code> 缺失或不支持时返回 415</td></tr><tr data-src-line="46" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@ResponseStatus</code></td><td style="text-align:left;">指定响应状态码</td><td style="text-align:left;">标在处理方法或异常类上；标在异常类上时由异常处理器读取</td></tr></tbody></table><h2 id="事务、缓存与异步" tabindex="-1" data-src-line="48" data-src-file="spring/reference/annotations.md">事务、缓存与异步 <a class="header-anchor" href="#事务、缓存与异步" aria-label="Permalink to &quot;事务、缓存与异步&quot;">​</a></h2><table tabindex="0"><thead data-src-line="50" data-src-file="spring/reference/annotations.md"><tr data-src-line="50" data-src-file="spring/reference/annotations.md"><th style="text-align:left;">注解</th><th style="text-align:left;">作用</th><th style="text-align:left;">约束与默认值</th></tr></thead><tbody data-src-line="52" data-src-file="spring/reference/annotations.md"><tr data-src-line="52" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Transactional</code></td><td style="text-align:left;">声明式事务</td><td style="text-align:left;">基于代理，同一个类内部的自调用不生效；默认只对 <code>RuntimeException</code> 和 <code>Error</code> 回滚</td></tr><tr data-src-line="53" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Cacheable</code> / <code>@CacheEvict</code></td><td style="text-align:left;">读取时缓存、失效时清除</td><td style="text-align:left;">需要 <code>@EnableCaching</code>；同类内部调用不经过代理，注解不生效</td></tr><tr data-src-line="54" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Async</code></td><td style="text-align:left;">异步执行</td><td style="text-align:left;">需要 <code>@EnableAsync</code>；返回 <code>void</code>、<code>Future</code> 或 <code>CompletableFuture</code>，同类内部调用不生效</td></tr><tr data-src-line="55" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Scheduled</code></td><td style="text-align:left;">定时执行</td><td style="text-align:left;">需要 <code>@EnableScheduling</code>；方法不接受参数，通常返回 <code>void</code></td></tr></tbody></table><h2 id="校验与异常" tabindex="-1" data-src-line="57" data-src-file="spring/reference/annotations.md">校验与异常 <a class="header-anchor" href="#校验与异常" aria-label="Permalink to &quot;校验与异常&quot;">​</a></h2><table tabindex="0"><thead data-src-line="59" data-src-file="spring/reference/annotations.md"><tr data-src-line="59" data-src-file="spring/reference/annotations.md"><th style="text-align:left;">注解</th><th style="text-align:left;">作用</th><th style="text-align:left;">约束与默认值</th></tr></thead><tbody data-src-line="61" data-src-file="spring/reference/annotations.md"><tr data-src-line="61" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Validated</code></td><td style="text-align:left;">触发方法参数校验</td><td style="text-align:left;">标在类上启用方法级校验；分组校验用它指定分组</td></tr><tr data-src-line="62" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@Valid</code></td><td style="text-align:left;">级联校验</td><td style="text-align:left;">标在字段或方法参数上；嵌套对象需要逐层标注</td></tr><tr data-src-line="63" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@ExceptionHandler</code></td><td style="text-align:left;">处理指定异常</td><td style="text-align:left;">只对所在控制器生效；全局处理放到 <code>@ControllerAdvice</code> 类</td></tr><tr data-src-line="64" data-src-file="spring/reference/annotations.md"><td style="text-align:left;"><code>@ControllerAdvice</code></td><td style="text-align:left;">全局异常与绑定处理</td><td style="text-align:left;">可用 <code>basePackages</code>、<code>annotations</code> 限定生效范围</td></tr></tbody></table><p data-src-line="66" data-src-file="spring/reference/annotations.md">查不到需要的注解时，先看它是否属于本页声明的范围；Spring Security、Spring Data、测试相关注解在各自专题里查。</p>',14)])])}const y=e(l,[["render",r]]);export{p as __pageData,y as default};
